     "summary": "新快报讯 记者陈钰涵报道 9月8日，广州海珠区教育局与华南师范大学、华南师范大学附属小学在华南师范大学正式签署合作办学协议。三方将携手合作创办“华南师范大学附属海珠小学（暂定名）”，这是海珠区首个华师合作办学公办小学。新学校选址于海珠区上涌果树公园北侧AH060922地块（大境花园西侧），规划办学规模18个教学班，预计2027年9月正式开办并启动起始年级招生。",
