     "summary": "从2026年上半年整车企业半年报中关于账期的数据来看，《通知》的出台有其必要性。Wind数据显示，截至二季度末，14家主流上市车企应付账款及票据合计7825.1亿元，较2025年期末增加175.5亿元；2025年中、2025年末、2026年中三个时间点的周转天数均值分别约为170天、164天和187天。也即今年上半年的账期较去年末延长约23天。",
